<script setup lang="ts">
import { ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
const auth=useAuthStore();const router=useRouter();const name=ref('');const email=ref('');const password=ref('');const confirm=ref('');const error=ref('')
async function submit(){error.value='';if(password.value!==confirm.value){error.value='Konfirmasi password tidak sama';return}try{await auth.register(email.value,name.value,password.value);router.push('/')}catch(e){error.value=e instanceof Error?e.message:'Registrasi gagal'}}
</script>
<template><section class="auth-card"><RouterLink to="/" class="brand auth-brand">Nusa<span>Mart</span></RouterLink><p class="eyebrow">MULAI BELANJA</p><h1>Buat akun NusaMart</h1><p class="auth-subtitle">Daftar untuk menyimpan keranjang dan riwayat pesanan.</p><form class="form-stack" @submit.prevent="submit"><label class="field-label">Nama lengkap<input v-model="name" autocomplete="name" required minlength="2" maxlength="120" placeholder="Nama kamu" /></label><label class="field-label">Email<input v-model="email" type="email" autocomplete="email" required placeholder="nama@email.com" /></label><label class="field-label">Password<input v-model="password" type="password" autocomplete="new-password" required minlength="8" placeholder="Minimal 8 karakter" /></label><label class="field-label">Konfirmasi password<input v-model="confirm" type="password" autocomplete="new-password" required minlength="8" placeholder="Ulangi password" /></label><p v-if="error" class="error-banner">{{ error }}</p><button class="button-primary full-button" :disabled="auth.busy">{{ auth.busy?'Membuat akun…':'Daftar' }}</button></form><p class="auth-switch">Sudah punya akun? <RouterLink to="/login">Masuk</RouterLink></p></section></template>
